SourceCode.Declaration:
/// <summary>
/// A device setup code (Mobile devices, New device setup code): what a new handheld scans to
/// join the fleet instead of a connection code with a client secret. Only the SHA-256 of the code
/// is kept; the code itself is shown once, in its QR code. A code works until it expires or has
/// been used MaxUses times. See HSMobileOpsDeviceSetupService and docs/device-setup.md.
/// </summary>
public class HSMobileOpsDeviceSetupCode extends common
{
}

Method.Source:
/// <summary>
/// The stored form of a code: lower-case hex SHA-256 of its UTF-8 text, trimmed and upper-cased.
/// </summary>
public static str hashOf(str _code)
{
    System.Security.Cryptography.SHA256 sha = System.Security.Cryptography.SHA256::Create();
    System.Text.Encoding                utf8 = System.Text.Encoding::get_UTF8();

    return strLwr(strReplace(System.BitConverter::ToString(
        sha.ComputeHash(utf8.GetBytes(strUpr(strLRTrim(_code))))), '-', ''));
}

/// <summary>
/// Whether the code can still set up a device: not expired, not used up.
/// </summary>
public boolean isOpen()
{
    return this.RecId
        && this.ExpiresUtc > DateTimeUtil::utcNow()
        && this.Uses < this.MaxUses;
}

/// <summary>
/// The token service address of the newest code - the default for the next one.
/// </summary>
public static str lastTokenServiceUrl()
{
    HSMobileOpsDeviceSetupCode setupCode;

    select firstOnly TokenServiceUrl from setupCode
        order by setupCode.CreatedDateTime desc
        where setupCode.TokenServiceUrl;
    return setupCode.TokenServiceUrl;
}
